[ -s "$DEX" ] || { echo "[失败] dex 写入失败"; exit 1; }

echo "[2/3] 写入 rish 脚本"
cat > "$RISH" <<'RISHSCRIPT'
#!/system/bin/sh
BASEDIR=$(dirname "$0")
DEX="$BASEDIR"/rish_shizuku.dex

if [ ! -f "$DEX" ]; then
  echo "Cannot find $DEX"
  exit 1
fi

if [ $(getprop ro.build.version.sdk) -ge 34 ]; then
  if [ -w "$DEX" ]; then
    chmod 400 "$DEX"
  fi
  if [ -w "$DEX" ]; then
    echo "Cannot remove write permission of $DEX"
    exit 1
  fi
fi

[ -z "$RISH_APPLICATION_ID" ] && export RISH_APPLICATION_ID="com.termux"
/system/bin/app_process -Djava.class.path="$DEX" /system/bin --nice-name=rish \
  rikka.shizuku.shell.ShizukuShellLoader "$@"
RISHSCRIPT

echo "[3/3] 设置权限"
chmod 700 "$RISH"
chmod 400 "$DEX" 2>/dev/null || true

echo ""
echo "安装完成。验证一下："
echo "  rish -c id"
echo "正常应输出 uid=2000(shell)"
echo "如果提示连不上，先在 Shizuku 里用无线调试启动服务。"
